import * as Cloudflare from "@/Cloudflare";
import { CloudflareEnvironment } from "@/Cloudflare/CloudflareEnvironment";
import { findZoneByName } from "@/Cloudflare/Zone/lookup";
import * as Provider from "@/Provider";
import * as Test from "@/Test/Alchemy";
import * as certificateAuthorities from "@distilled.cloud/cloudflare/certificate-authorities";
import * as mtls from "@distilled.cloud/cloudflare/mtls-certificates";
import { describe, expect } from "alchemy-test";
import * as Effect from "effect/Effect";
import { MinimumLogLevel } from "effect/References";
import * as Schedule from "effect/Schedule";
import { CA_CERT_1, CA_CERT_2 } from "./fixtures/certs.ts";
const { test } = Test.make({ providers: Cloudflare.providers() });

const logLevel = Effect.provideService(
  MinimumLogLevel,
  process.env.DEBUG ? "Debug" : "Info",
);

const zoneName =
  process.env.CLOUDFLARE_TEST_DNS_ZONE_NAME ?? "alchemy-test-2.us";

const resolveZoneId = Effect.gen(function* () {
  const { accountId } = yield* yield* CloudflareEnvironment;
  const zone = yield* findZoneByName({ accountId, name: zoneName });
  if (!zone) {
    return yield* Effect.die(
      new Error(`zone "${zoneName}" not found in account`),
    );
  }
  return zone.id;
});

// The scoped API token the test harness mints propagates eventually-
// consistently across Cloudflare's edge — a fresh token intermittently 403s
// with "Unable to authenticate request". Ride out the blips on the test's
// own out-of-band calls by retrying the typed `Forbidden` error (part of
// each operation's error union via distilled patches). Bounded:
// 6 retries of 500ms exponential backoff = max ~31.5s.
const forbiddenRetrySchedule = Schedule.exponential("500 millis");

const getHostnames = (zoneId: string, mtlsCertificateId?: string) =>
  certificateAuthorities
    .getHostnameAssociation({ zoneId, mtlsCertificateId })
    .pipe(
      Effect.map((r) => [...(r.hostnames ?? [])].sort()),
      Effect.retry({
        while: (e) => e._tag === "Forbidden",
        schedule: forbiddenRetrySchedule,
        times: 6,
      }),
    );

// Normalize the keyed association to a known (empty) baseline so each run
// starts from the same cloud state regardless of what a previous (possibly
// interrupted) run left behind.
const clearAssociation = (zoneId: string, mtlsCertificateId?: string) =>
  certificateAuthorities
    .putHostnameAssociation({ zoneId, mtlsCertificateId, hostnames: [] })
    .pipe(
      Effect.retry({
        while: (e) => e._tag === "Forbidden",
        schedule: forbiddenRetrySchedule,
        times: 6,
      }),
    );

// PUT→GET on the association is eventually consistent at the edge — poll
// with a typed, bounded retry until the observed set matches.
const waitForHostnames = (
  zoneId: string,
  expected: ReadonlyArray<string>,
  mtlsCertificateId?: string,
) =>
  getHostnames(zoneId, mtlsCertificateId).pipe(
    Effect.flatMap((observed) =>
      observed.length === expected.length &&
      observed.every((h, i) => h === [...expected].sort()[i])
        ? Effect.succeed(observed)
        : Effect.fail({ _tag: "HostnamesNotConverged", observed } as const),
    ),
    Effect.retry({
      while: (e) => e._tag === "HostnamesNotConverged",
      // Bounded: 25 polls x 3s = max ~75s. PUT→GET convergence at the edge
      // runs well past the earlier ~30s under full-suite parallel load (the
      // API is being throttled, which stretches the propagation window).
      schedule: Schedule.max([
        Schedule.spaced("3 seconds"),
        Schedule.recurs(25),
      ]),
    }),
  );

const waitForCertDelete = (accountId: string, mtlsCertificateId: string) =>
  mtls.getMtlsCertificate({ accountId, mtlsCertificateId }).pipe(
    Effect.flatMap((cert) =>
      cert.id === mtlsCertificateId
        ? Effect.fail({ _tag: "CertificateNotDeleted" } as const)
        : Effect.void,
    ),
    Effect.catchTag("CertificateNotFound", () => Effect.void),
    Effect.retry({
      while: (e) => e._tag === "CertificateNotDeleted",
      // Bounded: 30 polls x 3s = max ~90s of waiting. The CA certificate
      // delete only completes once the hostname-association clear (issued
      // first by destroy) has propagated, and under full-suite load that
      // combined window was observed to exceed the previous ~30s budget.
      schedule: Schedule.max([
        Schedule.spaced("3 seconds"),
        Schedule.recurs(30),
      ]),
    }),
  );

describe.sequential("HostnameAssociation", () => {
  test.provider(
    "pins Managed CA hostnames, updates in place, and clears on destroy",
    (stack) =>
      Effect.gen(function* () {
        const zoneId = yield* resolveZoneId;

        yield* stack.destroy();
        // Known baseline: no Managed CA hostname associations.
        yield* clearAssociation(zoneId);

        const created = yield* stack.deploy(
          Cloudflare.CertificateAuthorities.HostnameAssociation(
            "ManagedCaHosts",
            {
              zoneId,
              hostnames: [`mtls.${zoneName}`],
            },
          ),
        );

        expect(created.zoneId).toEqual(zoneId);
        expect(created.mtlsCertificateId).toBeUndefined();
        expect(created.hostnames).toEqual([`mtls.${zoneName}`]);

        yield* waitForHostnames(zoneId, [`mtls.${zoneName}`]);

        // In-place update — hostnames are the mutable aspect of the singleton.
        const updated = yield* stack.deploy(
          Cloudflare.CertificateAuthorities.HostnameAssociation(
            "ManagedCaHosts",
            {
              zoneId,
              hostnames: [`mtls2.${zoneName}`, `mtls.${zoneName}`],
            },
          ),
        );

        expect([...updated.hostnames].sort()).toEqual([
          `mtls.${zoneName}`,
          `mtls2.${zoneName}`,
        ]);

        yield* waitForHostnames(zoneId, [
          `mtls.${zoneName}`,
          `mtls2.${zoneName}`,
        ]);

        yield* stack.destroy();

        // Destroy cleared the association (PUT of an empty hostname list).
        yield* waitForHostnames(zoneId, []);
      }).pipe(logLevel),
    // Three sequential edge-convergence waits (create, update, clear), each up
    // to ~75s under throttled full-suite load, exceed the 120s default.
    { timeout: 300_000 },
  );

  test.provider(
    "associates hostnames with an uploaded CA and destroys before the cert",
    (stack) =>
      Effect.gen(function* () {
        const { accountId } = yield* yield* CloudflareEnvironment;
        const zoneId = yield* resolveZoneId;

        yield* stack.destroy();

        const { cert, assoc } = yield* stack.deploy(
          Effect.gen(function* () {
            const cert = yield* Cloudflare.MtlsCertificate.MtlsCertificate(
              "CertAuthCa",
              {
                ca: true,
                certificates: CA_CERT_1,
              },
            );
            const assoc =
              yield* Cloudflare.CertificateAuthorities.HostnameAssociation(
                "CaHosts",
                {
                  zoneId,
                  mtlsCertificateId: cert.mtlsCertificateId,
                  hostnames: [`mtls-ca.${zoneName}`],
                },
              );
            return { cert, assoc };
          }),
        );

        expect(cert.mtlsCertificateId).toBeDefined();
        expect(assoc.mtlsCertificateId).toEqual(cert.mtlsCertificateId);
        expect(assoc.hostnames).toEqual([`mtls-ca.${zoneName}`]);

        yield* waitForHostnames(
          zoneId,
          [`mtls-ca.${zoneName}`],
          cert.mtlsCertificateId,
        );

        // Destroy must clear the association before deleting the certificate —
        // Cloudflare refuses to delete a CA that hostnames still reference.
        yield* stack.destroy();

        yield* waitForCertDelete(accountId, cert.mtlsCertificateId);
      }).pipe(logLevel),
  );

  test.provider(
    "changing the certificate key replaces the association",
    (stack) =>
      Effect.gen(function* () {
        const { accountId } = yield* yield* CloudflareEnvironment;
        const zoneId = yield* resolveZoneId;

        yield* stack.destroy();
        yield* clearAssociation(zoneId);

        const first = yield* stack.deploy(
          Effect.gen(function* () {
            const assoc =
              yield* Cloudflare.CertificateAuthorities.HostnameAssociation(
                "ReplaceHosts",
                {
                  zoneId,
                  hostnames: [`mtls-replace.${zoneName}`],
                },
              );
            return { assoc };
          }),
        );

        expect(first.assoc.mtlsCertificateId).toBeUndefined();
        yield* waitForHostnames(zoneId, [`mtls-replace.${zoneName}`]);

        // mtlsCertificateId keys the association — switching from the Managed
        // CA to an uploaded CA is a replacement: the new keyed association is
        // created and the old Managed CA list is cleared as the old instance
        // deletes.
        const second = yield* stack.deploy(
          Effect.gen(function* () {
            const cert = yield* Cloudflare.MtlsCertificate.MtlsCertificate(
              "ReplaceCa",
              {
                ca: true,
                certificates: CA_CERT_2,
              },
            );
            const assoc =
              yield* Cloudflare.CertificateAuthorities.HostnameAssociation(
                "ReplaceHosts",
                {
                  zoneId,
                  mtlsCertificateId: cert.mtlsCertificateId,
                  hostnames: [`mtls-replace.${zoneName}`],
                },
              );
            return { cert, assoc };
          }),
        );

        expect(second.assoc.mtlsCertificateId).toEqual(
          second.cert.mtlsCertificateId,
        );

        yield* waitForHostnames(
          zoneId,
          [`mtls-replace.${zoneName}`],
          second.cert.mtlsCertificateId,
        );
        // The old Managed CA association was cleared by the replacement.
        yield* waitForHostnames(zoneId, []);

        yield* stack.destroy();

        yield* waitForCertDelete(accountId, second.cert.mtlsCertificateId);
      }).pipe(logLevel),
  );
});

import * as AWS from "@/AWS";
import { ServiceSpecificCredential, User } from "@/AWS/IAM";
import * as Provider from "@/Provider";
import * as Test from "@/Test/Alchemy";
import * as IAM from "@distilled.cloud/aws/iam";
import { describe, expect } from "alchemy-test";
import * as Effect from "effect/Effect";

const { test } = Test.make({ providers: AWS.providers() });

describe("AWS.IAM.ServiceSpecificCredential", () => {
  // Canonical `list()` test: IAM is a global service and service-specific
  // credentials are owned per IAM user, so the provider enumerates every user
  // first and then lists credentials per user. Deploy a real user + credential,
  // resolve the provider from context with the typed `findProvider`, call
  // `list()`, and assert the deployed credential appears in the result.
  test.provider(
    "list enumerates the deployed service-specific credential",
    (stack) =>
      Effect.gen(function* () {
        yield* stack.destroy();

        const deployed = yield* stack.deploy(
          Effect.gen(function* () {
            const user = yield* User("SsCredListOwner", {});
            const credential = yield* ServiceSpecificCredential(
              "SsCredListCred",
              {
                userName: user.userName,
                serviceName: "codecommit.amazonaws.com",
                // Duration.Input prop — converted to whole wire days.
                credentialAge: "30 days",
              },
            );
            return { user, credential };
          }),
        );

        // The Duration prop round-trips as an expiration ~30 days out, and
        // the creation-only secret is captured as a Redacted output.
        expect(deployed.credential.expirationDate).toBeDefined();
        expect(deployed.credential.servicePassword).toBeDefined();

        const provider = yield* Provider.findProvider(
          ServiceSpecificCredential,
        );
        const all = yield* provider.list();

        const found = all.find(
          (entry) =>
            entry.serviceSpecificCredentialId ===
            deployed.credential.serviceSpecificCredentialId,
        );
        expect(found).toBeDefined();
        expect(found?.userName).toBe(deployed.user.userName);
        expect(found?.serviceName).toBe("codecommit.amazonaws.com");
        expect(found?.servicePassword).toBeUndefined();
        expect(found?.serviceCredentialSecret).toBeUndefined();

        yield* stack.destroy();

        // The user (and with it the service-specific credential) is gone.
        const deletedUser = yield* IAM.getUser({
          UserName: deployed.user.userName,
        }).pipe(Effect.option);
        expect(deletedUser._tag).toBe("None");
      }),
  );
});

import * as iam from "@distilled.cloud/aws/iam";
import type * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import * as Stream from "effect/Stream";
import { isResolved } from "../../Diff.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import type { Providers } from "../Providers.ts";
import { toWireDays } from "../../Util/Duration.ts";
import { toRedactedString } from "./common.ts";

export interface ServiceSpecificCredentialProps {
  /**
   * User that owns the service-specific credential.
   */
  userName: string;
  /**
   * AWS service name that will consume the credential.
   */
  serviceName: string;
  /**
   * Optional credential validity duration, e.g. `"30 days"` or
   * `Duration.days(30)`. Sent to IAM as whole days (a bare number is
   * milliseconds). Changing it replaces the credential.
   */
  credentialAge?: Duration.Input;
  /**
   * Desired credential status.
   * @default "Active"
   */
  status?: iam.StatusType;
}

export interface ServiceSpecificCredential extends Resource<
  "AWS.IAM.ServiceSpecificCredential",
  ServiceSpecificCredentialProps,
  {
    /** The IAM user the credential belongs to. */
    userName: string;
    /** The AWS service the credential is scoped to (e.g. `codecommit.amazonaws.com`). */
    serviceName: string;
    /** The unique ID of the credential. */
    serviceSpecificCredentialId: string;
    /** Whether the credential is `Active` or `Inactive`. */
    status: iam.StatusType;
    /** When the credential was created. */
    createDate: Date | undefined;
    /** When the credential expires, if an age was configured. */
    expirationDate: Date | undefined;
    /** The generated service-specific user name. */
    serviceUserName: string | undefined;
    /** The generated credential alias, if the service issues one. */
    serviceCredentialAlias: string | undefined;
    /** The generated password. AWS only returns it at creation; later reads preserve the originally stored redacted value. */
    servicePassword: Redacted.Redacted<string> | undefined;
    /** The generated secret. AWS only returns it at creation; later reads preserve the originally stored redacted value. */
    serviceCredentialSecret: Redacted.Redacted<string> | undefined;
  },
  never,
  Providers
> {}

/**
 * A service-specific IAM credential.
 *
 * `ServiceSpecificCredential` creates service-bound credentials such as
 * CodeCommit HTTPS passwords for an IAM user. AWS only returns the secret
 * fields during creation, so subsequent reads preserve the originally stored
 * redacted values.
 * @resource
 * @section Managing Service Credentials
 * @example Create a CodeCommit Credential
 * ```typescript
 * const user = yield* User("CodeCommitUser", {
 *   userName: "codecommit-user",
 * });
 *
 * const credential = yield* ServiceSpecificCredential("CodeCommitCredential", {
 *   userName: user.userName,
 *   serviceName: "codecommit.amazonaws.com",
 * });
 * ```
 */
export const ServiceSpecificCredential = Resource<ServiceSpecificCredential>(
  "AWS.IAM.ServiceSpecificCredential",
);

export const ServiceSpecificCredentialProvider = () =>
  Provider.succeed(ServiceSpecificCredential, {
    stables: ["serviceSpecificCredentialId"],
    list: Effect.fn(function* () {
      // Service-specific credentials are owned per IAM user and IAM is a
      // global service, so enumerate every user in the account
      // (`listUsers`) and fan out `listServiceSpecificCredentials` per user
      // (bounded concurrency). Omit `ServiceName` to capture credentials
      // across all services. The credential secret is only returned at
      // creation, so list cannot recover it — match `read` and leave the
      // redacted secret fields undefined.
      const users = yield* iam.listUsers.pages({}).pipe(
        Stream.runCollect,
        Effect.map((chunk) => Array.from(chunk).flatMap((page) => page.Users)),
      );
      const perUser = yield* Effect.forEach(
        users,
        (user) =>
          iam.listServiceSpecificCredentials({ UserName: user.UserName }).pipe(
            Effect.map((response) =>
              (response.ServiceSpecificCredentials ?? []).map((metadata) => ({
                userName: metadata.UserName,
                serviceName: metadata.ServiceName,
                serviceSpecificCredentialId:
                  metadata.ServiceSpecificCredentialId,
                status: metadata.Status,
                createDate: metadata.CreateDate,
                expirationDate: metadata.ExpirationDate,
                serviceUserName: metadata.ServiceUserName,
                serviceCredentialAlias: metadata.ServiceCredentialAlias,
                servicePassword: undefined,
                serviceCredentialSecret: undefined,
              })),
            ),
            // The user may be deleted between enumeration and per-user list.
            Effect.catchTag("NoSuchEntityException", () => Effect.succeed([])),
          ),
        { concurrency: 10 },
      );
      return perUser.flat();
    }),
    diff: Effect.fn(function* ({ olds, news }) {
      if (!isResolved(news)) return;
      if (
        olds.userName !== news.userName ||
        olds.serviceName !== news.serviceName ||
        toWireDays(olds.credentialAge) !== toWireDays(news.credentialAge)
      ) {
        return { action: "replace" } as const;
      }
    }),
    read: Effect.fn(function* ({ output }) {
      if (!output) {
        return undefined;
      }
      const listed = yield* iam.listServiceSpecificCredentials({
        UserName: output.userName,
        ServiceName: output.serviceName,
      });
      const metadata = listed.ServiceSpecificCredentials?.find(
        (entry) =>
          entry.ServiceSpecificCredentialId ===
          output.serviceSpecificCredentialId,
      );
      if (!metadata?.ServiceSpecificCredentialId) {
        return undefined;
      }
      return {
        userName: metadata.UserName,
        serviceName: metadata.ServiceName,
        serviceSpecificCredentialId: metadata.ServiceSpecificCredentialId,
        status: metadata.Status,
        createDate: metadata.CreateDate,
        expirationDate: metadata.ExpirationDate,
        serviceUserName: metadata.ServiceUserName,
        serviceCredentialAlias: metadata.ServiceCredentialAlias,
        servicePassword: output.servicePassword,
        serviceCredentialSecret: output.serviceCredentialSecret,
      };
    }),
    reconcile: Effect.fn(function* ({ news, output, session }) {
      // Observe — credential ids are AWS-generated; we can only locate
      // the existing record via the prior output. The credential's
      // identity (userName, serviceName, age) is immutable (`diff`
      // triggers replacement on change), so a missing credential always
      // requires recreation.
      const observed = output
        ? yield* iam
            .listServiceSpecificCredentials({
              UserName: output.userName,
              ServiceName: output.serviceName,
            })
            .pipe(
              Effect.map((r) =>
                r.ServiceSpecificCredentials?.find(
                  (entry) =>
                    entry.ServiceSpecificCredentialId ===
                    output.serviceSpecificCredentialId,
                ),
              ),
              Effect.catchTag("NoSuchEntityException", () =>
                Effect.succeed(undefined),
              ),
            )
        : undefined;

      // Ensure — create when missing. The secret fields are only
      // returned on first creation, so adoption preserves the prior
      // redacted values.
      let credentialId =
        observed?.ServiceSpecificCredentialId ??
        output?.serviceSpecificCredentialId;
      let userName = observed?.UserName ?? output?.userName ?? news.userName;
      let serviceName =
        observed?.ServiceName ?? output?.serviceName ?? news.serviceName;
      let createDate = observed?.CreateDate ?? output?.createDate;
      let expirationDate = observed?.ExpirationDate ?? output?.expirationDate;
      let serviceUserName =
        observed?.ServiceUserName ?? output?.serviceUserName;
      let serviceCredentialAlias =
        observed?.ServiceCredentialAlias ?? output?.serviceCredentialAlias;
      let servicePassword = output?.servicePassword;
      let serviceCredentialSecret = output?.serviceCredentialSecret;
      let observedStatus = observed?.Status ?? output?.status;

      if (!observed) {
        const created = yield* iam.createServiceSpecificCredential({
          UserName: news.userName,
          ServiceName: news.serviceName,
          CredentialAgeDays: toWireDays(news.credentialAge),
        });
        const credential = created.ServiceSpecificCredential;
        if (!credential?.ServiceSpecificCredentialId) {
          return yield* Effect.fail(
            new Error(
              `createServiceSpecificCredential returned no credential id`,
            ),
          );
        }
        credentialId = credential.ServiceSpecificCredentialId;
        userName = credential.UserName;
        serviceName = credential.ServiceName;
        createDate = credential.CreateDate;
        expirationDate = credential.ExpirationDate;
        serviceUserName = credential.ServiceUserName;
        serviceCredentialAlias = credential.ServiceCredentialAlias;
        servicePassword = toRedactedString(credential.ServicePassword);
        serviceCredentialSecret = toRedactedString(
          credential.ServiceCredentialSecret,
        );
        observedStatus = credential.Status;
      }

      if (!credentialId) {
        return yield* Effect.fail(
          new Error(
            `ServiceSpecificCredential for user '${news.userName}' has no id`,
          ),
        );
      }

      // Sync — apply the desired status when it differs from observed.
      const desiredStatus = news.status ?? observedStatus ?? "Active";
      if (desiredStatus !== observedStatus) {
        yield* iam.updateServiceSpecificCredential({
          UserName: userName,
          ServiceSpecificCredentialId: credentialId,
          Status: desiredStatus,
        });
      }

      yield* session.note(credentialId);
      return {
        userName,
        serviceName,
        serviceSpecificCredentialId: credentialId,
        status: desiredStatus,
        createDate,
        expirationDate,
        serviceUserName,
        serviceCredentialAlias,
        servicePassword,
        serviceCredentialSecret,
      };
    }),
    delete: Effect.fn(function* ({ output }) {
      yield* iam
        .deleteServiceSpecificCredential({
          UserName: output.userName,
          ServiceSpecificCredentialId: output.serviceSpecificCredentialId,
        })
        .pipe(Effect.catchTag("NoSuchEntityException", () => Effect.void));
    }),
  });

import * as Cloudflare from "@/Cloudflare";
import { CloudflareEnvironment } from "@/Cloudflare/CloudflareEnvironment";
import { findZoneByName } from "@/Cloudflare/Zone/lookup";
import * as Provider from "@/Provider";
import * as Test from "@/Test/Alchemy";
import * as originTls from "@distilled.cloud/cloudflare/origin-tls-client-auth";
import { describe, expect } from "alchemy-test";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import { MinimumLogLevel } from "effect/References";
import * as Schedule from "effect/Schedule";
import { CERT_5, CERT_6, KEY_5, KEY_6 } from "./fixtures/certs.ts";

const { test } = Test.make({ providers: Cloudflare.providers() });

const logLevel = Effect.provideService(
  MinimumLogLevel,
  process.env.DEBUG ? "Debug" : "Info",
);

const zoneName =
  process.env.CLOUDFLARE_TEST_DNS_ZONE_NAME ?? "alchemy-test-2.us";

// Deterministic per-test hostnames. Each test owns a disjoint subdomain so
// reruns never collide (never derive names from Date.now()/random).
const HOST_LIFECYCLE = `alchemy-aop-assoc.${zoneName}`;
const HOST_REPLACE_A = `alchemy-aop-assoc-replace-a.${zoneName}`;
const HOST_REPLACE_B = `alchemy-aop-assoc-replace-b.${zoneName}`;

const resolveZoneId = Effect.gen(function* () {
  const { accountId } = yield* yield* CloudflareEnvironment;
  const zone = yield* findZoneByName({ accountId, name: zoneName });
  if (!zone) {
    return yield* Effect.die(
      new Error(`zone "${zoneName}" not found in account`),
    );
  }
  return zone.id;
});

// The scoped API token the test harness mints propagates eventually-
// consistently across Cloudflare's edge — a fresh token intermittently 403s
// with "Unable to authenticate request". Ride out the blips on the test's
// own out-of-band calls by retrying the typed `Forbidden` error (part of
// each operation's error union via distilled patches).
const forbiddenRetrySchedule = Schedule.exponential("500 millis");

// Read a hostname's association out-of-band; "never configured" (404 / code
// 1553) and "voided" (`enabled: null`) both read as undefined.
const getAssociation = (zoneId: string, hostname: string) =>
  originTls.getHostname({ zoneId, hostname }).pipe(
    Effect.map((assoc) =>
      assoc.enabled === null || assoc.enabled === undefined ? undefined : assoc,
    ),
    Effect.catchTag("HostnameAssociationNotFound", () =>
      Effect.succeed(undefined),
    ),
    Effect.retry({
      while: (e) => e._tag === "Forbidden",
      schedule: forbiddenRetrySchedule,
      times: 8,
    }),
  );

// Void any association left behind by interrupted runs so the test starts
// from a clean slate.
const voidAssociation = (zoneId: string, hostname: string) =>
  Effect.gen(function* () {
    const observed = yield* getAssociation(zoneId, hostname);
    if (!observed?.certId) return;
    yield* originTls
      .putHostname({
        zoneId,
        config: [{ hostname, certId: observed.certId, enabled: null }],
      })
      .pipe(
        // The pinned certificate may already be gone (code 1415); the
        // association is inert without it.
        Effect.catchTag("InvalidHostnameConfig", () => Effect.void),
      );
  });

// Purge any live hostname client certificates with this suite's fixture PEMs
// left behind by interrupted runs. Filtering by PEM content keeps the purge
// scoped to this file — other suites in the directory own other fixtures.
const purgeCertificates = (zoneId: string, pems: string[]) =>
  Effect.gen(function* () {
    const list = yield* originTls.listHostnameCertificates({ zoneId }).pipe(
      Effect.retry({
        while: (e) => e._tag === "Forbidden",
        schedule: forbiddenRetrySchedule,
        times: 8,
      }),
    );
    const targets = pems.map((p) => p.trim());
    yield* Effect.forEach(
      list.result.filter(
        (c) =>
          c.id &&
          c.status !== "deleted" &&
          c.status !== "pending_deletion" &&
          targets.includes((c.certificate ?? "").trim()),
      ),
      (c) =>
        originTls
          .deleteHostnameCertificate({ zoneId, certificateId: c.id! })
          .pipe(
            Effect.retry({
              while: (e) =>
                e._tag === "CertificatePendingDeployment" ||
                e._tag === "HostnameCertificateInUse",
              schedule: Schedule.spaced("5 seconds"),
              times: 10,
            }),
            Effect.catchTag(
              ["HostnameCertificateNotFound", "CertificatePendingDeletion"],
              () => Effect.void,
            ),
          ),
    );
  });

// Both certificates stay deployed across every step so updates/replacements
// only touch the association itself (replacing a resource while removing its
// old dependency in the same deploy is a known engine deadlock).
const program = (opts: {
  zoneId: string;
  hostname: string;
  cert: "5" | "6";
  enabled: boolean;
}) =>
  Effect.gen(function* () {
    const cert5 = yield* Cloudflare.OriginTlsClientAuth.HostnameCertificate(
      "AssocCert5",
      {
        zoneId: opts.zoneId,
        certificate: CERT_5,
        privateKey: Redacted.make(KEY_5),
      },
    );
    const cert6 = yield* Cloudflare.OriginTlsClientAuth.HostnameCertificate(
      "AssocCert6",
      {
        zoneId: opts.zoneId,
        certificate: CERT_6,
        privateKey: Redacted.make(KEY_6),
      },
    );
    const pinned = opts.cert === "6" ? cert6 : cert5;
    const association =
      yield* Cloudflare.OriginTlsClientAuth.HostnameAssociation("AopHost", {
        zoneId: opts.zoneId,
        hostname: opts.hostname,
        certId: pinned.certificateId,
        enabled: opts.enabled,
      });
    return { cert5, cert6, association };
  });

describe.skipIf(!!process.env.FAST)("HostnameAssociation", () => {
  // Hostname associations are keyed entirely by {zoneId, hostname} and
  // Cloudflare exposes no endpoint that enumerates which hostnames in a zone
  // have an AOP association, so `list()` is non-listable and returns []. This
  // read-only assertion always runs (no cert/hostname deploy required).
  test.provider("list returns [] for the non-listable association", (stack) =>
    Effect.gen(function* () {
      yield* stack.destroy();

      const provider = yield* Provider.findProvider(
        Cloudflare.OriginTlsClientAuth.HostnameAssociation,
      );
      const all = yield* provider.list();
      expect(all).toEqual([]);

      yield* stack.destroy();
    }).pipe(Effect.ensuring(stack.destroy().pipe(Effect.ignore)), logLevel),
  );

  test.provider(
    "associates a hostname, updates cert and enablement in place, voids on destroy",
    (stack) =>
      Effect.gen(function* () {
        const zoneId = yield* resolveZoneId;

        yield* stack.destroy();
        yield* voidAssociation(zoneId, HOST_LIFECYCLE);
        yield* purgeCertificates(zoneId, [CERT_5, CERT_6]);

        // Create — pin cert 5, enabled.
        const initial = yield* stack.deploy(
          program({
            zoneId,
            hostname: HOST_LIFECYCLE,
            cert: "5",
            enabled: true,
          }),
        );

        expect(initial.association.zoneId).toEqual(zoneId);
        expect(initial.association.hostname).toEqual(HOST_LIFECYCLE);
        expect(initial.association.certId).toEqual(initial.cert5.certificateId);
        expect(initial.association.enabled).toEqual(true);

        const observed = yield* getAssociation(zoneId, HOST_LIFECYCLE);
        expect(observed?.certId).toEqual(initial.cert5.certificateId);
        expect(observed?.enabled).toEqual(true);

        // Update in place — repin to cert 6 and disable enforcement.
        const updated = yield* stack.deploy(
          program({
            zoneId,
            hostname: HOST_LIFECYCLE,
            cert: "6",
            enabled: false,
          }),
        );

        expect(updated.association.hostname).toEqual(HOST_LIFECYCLE);
        expect(updated.association.certId).toEqual(updated.cert6.certificateId);
        expect(updated.association.enabled).toEqual(false);

        const reobserved = yield* getAssociation(zoneId, HOST_LIFECYCLE);
        expect(reobserved?.certId).toEqual(updated.cert6.certificateId);
        expect(reobserved?.enabled).toEqual(false);

        // Destroy — the association is voided (`enabled: null`).
        yield* stack.destroy();

        const gone = yield* getAssociation(zoneId, HOST_LIFECYCLE).pipe(
          Effect.flatMap((assoc) =>
            assoc === undefined
              ? Effect.void
              : Effect.fail({ _tag: "AssociationNotVoided" } as const),
          ),
          // Frequent, bounded spaced poll (~240s): voiding settles through
          // edge propagation asynchronously and can occasionally take well
          // past two minutes, so poll every 5s with a generous bound rather
          // than backing off exponentially (whose late gaps overshoot).
          Effect.retry({
            while: (e) => e._tag === "AssociationNotVoided",
            schedule: Schedule.spaced("5 seconds"),
            times: 48,
          }),
          Effect.map(() => true),
        );
        expect(gone).toEqual(true);
      }).pipe(Effect.ensuring(stack.destroy().pipe(Effect.ignore)), logLevel),
    // Two sequential deploys, each uploading two hostname client-certificates
    // plus the association, on Cloudflare's per-zone-serialized client-cert
    // API. Under a full concurrent `./test/Cloudflare` run this zone's cert
    // mutations contend with the sibling Certificate/HostnameCertificate
    // suites (each create/delete bounded-retries the per-zone 409), then a
    // ~240s spaced void poll — give real headroom while staying bounded.
    { timeout: 420_000 },
  );

  test.provider(
    "replaces the association when the hostname changes",
    (stack) =>
      Effect.gen(function* () {
        const zoneId = yield* resolveZoneId;

        yield* stack.destroy();
        yield* voidAssociation(zoneId, HOST_REPLACE_A);
        yield* voidAssociation(zoneId, HOST_REPLACE_B);
        yield* purgeCertificates(zoneId, [CERT_5, CERT_6]);

        const initial = yield* stack.deploy(
          program({
            zoneId,
            hostname: HOST_REPLACE_A,
            cert: "5",
            enabled: true,
          }),
        );
        expect(initial.association.hostname).toEqual(HOST_REPLACE_A);

        // Changing the hostname is a replacement — the old hostname's
        // association is voided and the new hostname gets its own entry.
        const replaced = yield* stack.deploy(
          program({
            zoneId,
            hostname: HOST_REPLACE_B,
            cert: "5",
            enabled: true,
          }),
        );
        expect(replaced.association.hostname).toEqual(HOST_REPLACE_B);
        expect(replaced.association.certId).toEqual(
          replaced.cert5.certificateId,
        );

        const observedNew = yield* getAssociation(zoneId, HOST_REPLACE_B);
        expect(observedNew?.enabled).toEqual(true);

        // The old hostname's association must be voided by the replacement.
        const oldGone = yield* getAssociation(zoneId, HOST_REPLACE_A).pipe(
          Effect.flatMap((assoc) =>
            assoc === undefined
              ? Effect.void
              : Effect.fail({ _tag: "AssociationNotVoided" } as const),
          ),
          // Frequent, bounded spaced poll (~120s): voiding settles through
          // edge propagation asynchronously, so check every 5s rather than
          // backing off exponentially (whose late gaps overshoot the timeout).
          Effect.retry({
            while: (e) => e._tag === "AssociationNotVoided",
            schedule: Schedule.spaced("5 seconds"),
            times: 24,
          }),
          Effect.map(() => true),
        );
        expect(oldGone).toEqual(true);

        yield* stack.destroy();

        // Voiding is asynchronous (the void PUT settles through edge
        // propagation) — poll until the association reads as absent rather
        // than asserting on a single (potentially stale) read.
        const newGone = yield* getAssociation(zoneId, HOST_REPLACE_B).pipe(
          Effect.flatMap((assoc) =>
            assoc === undefined
              ? Effect.void
              : Effect.fail({ _tag: "AssociationNotVoided" } as const),
          ),
          // Frequent, bounded spaced poll (~120s): voiding settles through
          // edge propagation asynchronously, so check every 5s rather than
          // backing off exponentially (whose late gaps overshoot the timeout).
          Effect.retry({
            while: (e) => e._tag === "AssociationNotVoided",
            schedule: Schedule.spaced("5 seconds"),
            times: 24,
          }),
          Effect.map(() => true),
        );
        expect(newGone).toEqual(true);
      }).pipe(Effect.ensuring(stack.destroy().pipe(Effect.ignore)), logLevel),
    // Same per-zone-serialized client-cert contention as the lifecycle case
    // above, plus two spaced void polls — give real headroom under load.
    { timeout: 300_000 },
  );
});

import { Effect, Layer, Redacted } from "effect"
import { Authorization, CurrentUser, Unauthorized } from "../api/Authorization.ts"
import { User, UserId } from "../domain/User.ts"

// The implementation of the Authorization middleware. It is seperate from the
// service definition to avoid leaking it into a client.
export const AuthorizationLayer = Layer.effect(
  Authorization,
  Effect.gen(function*() {
    // Here you could access services required by the middleware, like a
    // database or an external auth provider.
    yield* Effect.logInfo("Starting Authorization middleware")

    return Authorization.of({
      bearer: Effect.fn(function*(httpEffect, { credential }) {
        // Validate the token and return an Unauthorized error if it's invalid.
        const token = Redacted.value(credential)
        if (token !== "dev-token") {
          return yield* new Unauthorized({ message: "Missing or invalid bearer token" })
        }

        // Provide the current user to the rest of the stack. This will be
        // available in any endpoint or middleware that runs after this one.
        return yield* Effect.provideService(
          httpEffect,
          CurrentUser,
          new User({
            id: UserId.make(1),
            name: "Dev User",
            email: "dev@acme.com"
          })
        )
      })
    })
  })
)

import { describe, expect, it } from "vite-plus/test";

import {
  normalizeLinuxPasswordStorePreference,
  resolveLinuxPasswordStoreSwitch,
  resolveLinuxSecretStorageUnavailableMessage,
} from "./linuxSecretStorage.ts";

const autoSwitch = (env: NodeJS.ProcessEnv) =>
  resolveLinuxPasswordStoreSwitch({ preference: "auto", env });

describe("linuxSecretStorage", () => {
  it("preserves explicit supported password-store preferences", () => {
    expect(normalizeLinuxPasswordStorePreference("gnome-libsecret")).toBe("gnome-libsecret");
    expect(normalizeLinuxPasswordStorePreference("kwallet")).toBe("kwallet");
    expect(normalizeLinuxPasswordStorePreference("kwallet5")).toBe("kwallet5");
    expect(normalizeLinuxPasswordStorePreference("kwallet6")).toBe("kwallet6");
  });

  it("falls back to auto for missing or unsupported preferences", () => {
    expect(normalizeLinuxPasswordStorePreference(undefined)).toBe("auto");
    expect(normalizeLinuxPasswordStorePreference("basic")).toBe("auto");
  });

  it("uses explicit preferences instead of the auto heuristic", () => {
    for (const preference of ["gnome-libsecret", "kwallet", "kwallet5", "kwallet6"] as const) {
      expect(
        resolveLinuxPasswordStoreSwitch({ preference, env: { XDG_CURRENT_DESKTOP: "niri" } }),
      ).toBe(preference);
      // An explicit preference also wins where auto would have stayed out of the way.
      expect(
        resolveLinuxPasswordStoreSwitch({ preference, env: { XDG_CURRENT_DESKTOP: "KDE" } }),
      ).toBe(preference);
    }
  });

  it("leaves canonical KDE sessions to Electron's own wallet selection", () => {
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "KDE" })).toBeNull();
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "KDE", KDE_SESSION_VERSION: "6" })).toBeNull();
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "KDE", KDE_SESSION_VERSION: "5" })).toBeNull();
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "KDE:plasma" })).toBeNull();
  });

  it("does not force a password-store for desktops Electron already recognizes", () => {
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "GNOME" })).toBeNull();
    for (const desktop of ["Deepin", "Pantheon", "UKUI", "Unity", "X-Cinnamon", "XFCE"]) {
      expect(autoSwitch({ XDG_CURRENT_DESKTOP: desktop })).toBeNull();
    }
  });

  it("recognizes a known desktop later in a colon-separated XDG_CURRENT_DESKTOP list", () => {
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "niri:GNOME" })).toBeNull();
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "ubuntu:GNOME" })).toBeNull();
  });

  it("forces gnome-libsecret for unrecognized Linux desktop sessions", () => {
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "niri" })).toBe("gnome-libsecret");
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "Hyprland" })).toBe("gnome-libsecret");
    expect(autoSwitch({})).toBe("gnome-libsecret");
  });

  it("forces gnome-libsecret for desktops Electron recognizes but leaves on basic text", () => {
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "LXQt" })).toBe("gnome-libsecret");
    // Chromium stops at the first recognized value, so a later name cannot rescue the session.
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "LXQt:GNOME" })).toBe("gnome-libsecret");
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "LXQt:KDE" })).toBe("gnome-libsecret");
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "LXQt:plasma" })).toBe("gnome-libsecret");
  });

  it("does not treat lowercase desktop names as ones Electron recognizes", () => {
    // Chromium matches these case-sensitively, so lowercase spellings reach basic text.
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "gnome" })).toBe("gnome-libsecret");
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "xfce" })).toBe("gnome-libsecret");
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "kde", KDE_SESSION_VERSION: "6" })).toBe(
      "gnome-libsecret",
    );
  });

  it("overrides KDE sessions identified only by legacy variables", () => {
    // Chromium reaches KWallet4 for some of these, such as DESKTOP_SESSION=kde with a version, and
    // basic text for the rest. Either way these are the variables a previous session leaves behind,
    // so they are treated as unproven and forced to a real keyring rather than a guessed wallet.
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "plasma" })).toBe("gnome-libsecret");
    for (const session of [
      "kde",
      "kde-plasma",
      "kde4",
      "plasma",
      "plasmawayland",
      "plasmawayland-dev",
      "plasmax11",
      "plasmax11-dev",
    ]) {
      expect(autoSwitch({ DESKTOP_SESSION: session })).toBe("gnome-libsecret");
      expect(autoSwitch({ XDG_SESSION_DESKTOP: session })).toBe("gnome-libsecret");
      expect(autoSwitch({ GDMSESSION: session })).toBe("gnome-libsecret");
    }
    expect(autoSwitch({ DESKTOP_SESSION: "kde", KDE_SESSION_VERSION: "6" })).toBe(
      "gnome-libsecret",
    );
    expect(autoSwitch({ KDE_SESSION_VERSION: "6" })).toBe("gnome-libsecret");
    expect(autoSwitch({ KDE_FULL_SESSION: "true", KDE_SESSION_VERSION: "6" })).toBe(
      "gnome-libsecret",
    );
  });

  it("ignores stale session hints when XDG_CURRENT_DESKTOP is authoritative", () => {
    expect(
      autoSwitch({ XDG_CURRENT_DESKTOP: "niri", DESKTOP_SESSION: "gnome", GDMSESSION: "gnome" }),
    ).toBe("gnome-libsecret");
    // A previous KDE session left these behind; the compositor running now is not KDE.
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "niri", KDE_SESSION_VERSION: "6" })).toBe(
      "gnome-libsecret",
    );
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "niri", XDG_SESSION_DESKTOP: "GNOME" })).toBe(
      "gnome-libsecret",
    );
    expect(autoSwitch({ XDG_CURRENT_DESKTOP: "niri:plasma" })).toBe("gnome-libsecret");
    expect(
      autoSwitch({
        XDG_CURRENT_DESKTOP: "Hyprland",
        XDG_SESSION_DESKTOP: "KDE",
        KDE_SESSION_VERSION: "6",
      }),
    ).toBe("gnome-libsecret");
  });

  it("uses GNOME Keyring remediation for libsecret and unknown backends", () => {
    expect(
      resolveLinuxSecretStorageUnavailableMessage({
        configuredPreference: "auto",
        selectedBackend: "gnome_libsecret",
        env: { XDG_CURRENT_DESKTOP: "niri" },
      }),
    ).toContain("GNOME Keyring");
  });

  it("prefers explicit libsecret selection over KDE desktop heuristics", () => {
    expect(
      resolveLinuxSecretStorageUnavailableMessage({
        configuredPreference: "gnome-libsecret",
        selectedBackend: "unknown",
        env: { XDG_CURRENT_DESKTOP: "KDE" },
      }),
    ).toContain("GNOME Keyring");
    expect(
      resolveLinuxSecretStorageUnavailableMessage({
        configuredPreference: "auto",
        selectedBackend: "gnome_libsecret",
        env: { XDG_CURRENT_DESKTOP: "KDE" },
      }),
    ).toContain("GNOME Keyring");
  });

  it("prefers explicit KWallet preference over selected gnome-libsecret backend", () => {
    expect(
      resolveLinuxSecretStorageUnavailableMessage({
        configuredPreference: "kwallet6",
        selectedBackend: "gnome_libsecret",
        env: { XDG_CURRENT_DESKTOP: "niri" },
      }),
    ).toContain("KWallet");
    expect(
      resolveLinuxSecretStorageUnavailableMessage({
        configuredPreference: "kwallet",
        selectedBackend: "gnome-libsecret",
        env: {},
      }),
    ).toContain("KWallet");
  });

  it("uses KWallet remediation wording for KDE-looking sessions", () => {
    expect(
      resolveLinuxSecretStorageUnavailableMessage({
        configuredPreference: "auto",
        selectedBackend: "kwallet6",
        env: {},
      }),
    ).toContain("KWallet");
    expect(
      resolveLinuxSecretStorageUnavailableMessage({
        configuredPreference: "auto",
        selectedBackend: "unknown",
        env: { XDG_CURRENT_DESKTOP: "KDE" },
      }),
    ).toContain("KWallet");
    expect(
      resolveLinuxSecretStorageUnavailableMessage({
        configuredPreference: "auto",
        selectedBackend: "unknown",
        env: { DESKTOP_SESSION: "plasmawayland" },
      }),
    ).toContain("KWallet");
    // A desktop name outranks a bare KDE marker when choosing the wording.
    expect(
      resolveLinuxSecretStorageUnavailableMessage({
        configuredPreference: "auto",
        selectedBackend: "unknown",
        env: { GDMSESSION: "gnome", KDE_FULL_SESSION: "true" },
      }),
    ).toContain("GNOME Keyring");
  });
});
